// Baut Titel + Ticket-Body aus dem JSON-Bericht, den nightly-worker-wake.sh
// (ansible/roles/nightly_worker_wake) am Ende jedes 01:00-Uhr-Laufs schickt.
// Erwartetes Payload-Format siehe docs/59-nightly-worker-update.md.
const payload = $input.item.json.body || $input.item.json;

function fmtDuration(sec) {
  if (sec === undefined || sec === null) return 'unbekannt';
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return `${m}m ${s}s`;
}

const STATUS_TEXT = {
  pending: 'nie gestartet (unerwarteter Skriptabbruch davor)',
  not_ready: 'nicht aufgewacht',
  no_template: 'kein Semaphore-Projekt/Template gefunden',
  success: 'Update erfolgreich',
  error: 'Update-Task mit Fehler beendet',
  stopped: 'Update abgebrochen (Zeitbudget erreicht)',
};

const workers = payload.workers || [];
let anyProblem = false;

const workerBlocks = workers.map((w) => {
  const lines = [`### ${w.name}`];
  const statusText = STATUS_TEXT[w.status] || w.status;
  const ok = w.status === 'success';
  if (!ok) anyProblem = true;

  lines.push(`- Status: ${statusText}`);
  if (w.reason) lines.push(`- Grund: ${w.reason}`);
  if (w.status === 'success' || w.status === 'error' || w.status === 'stopped') {
    lines.push(`- Pakete geändert: ${w.changed ? 'ja' : 'nein'}`);
  }
  if (w.play_recap) lines.push(`- Ansible-Zusammenfassung: \`${w.play_recap}\``);
  if (w.rebooted) {
    lines.push('- Automatisch neu gestartet (Kernel-/libc-Update, reboot-required war gesetzt).');
  }
  return lines.join('\n');
}).join('\n\n');

const overallOk = payload.note ? false : !anyProblem;
const title = overallOk
  ? 'Nightly Worker Update: OK'
  : 'Nightly Worker Update: Fehler/Hinweis';
const dryRunPrefix = payload.dry_run ? '[DRY RUN] ' : '';

const bodyText = [
  `${dryRunPrefix}Nächtlicher Update-Lauf (worker-0/worker-1) ${overallOk ? 'erfolgreich' : 'mit Problemen'} abgeschlossen.`,
  '',
  `Gestartet: ${payload.started_at || 'unbekannt'}`,
  `Beendet: ${payload.finished_at || 'unbekannt'}`,
  `Dauer: ${fmtDuration(payload.elapsed_seconds)}`,
  payload.note ? `\nHinweis: ${payload.note}` : null,
  '',
  workerBlocks || '(keine Worker konfiguriert)',
  '',
  'Details: docs/59-nightly-worker-update.md im capulus-core-Repo, oder `journalctl -u nightly-worker-wake` auf dem Homeserver.',
].filter((l) => l !== null).join('\n');

return [{ json: { title: `${dryRunPrefix}${title}`, body: bodyText } }];
